import path from 'node:path';

/**
 * Where database files live. Kept free of other imports so drizzle.config.ts can use it too.
 */

/** Generated by `npm run db:generate`, applied by the app at start-up. Relative to the project root. */
export const MIGRATIONS_DIR = 'src/lib/server/db/migrations';

export const databaseFile = (dataDir: string) => path.join(dataDir, 'chloris.db');

export const backupsDir = (dataDir: string) => path.join(dataDir, 'backups');
